using System.Collections.Concurrent;
using System.Text.Json;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

public sealed record OsmWorldImportRequest(GeoBounds Bounds,double MetresPerTile=1,int SectionSize=1024,int OriginCellX=100,int OriginCellY=100,int Seed=42,string Name="OpenStreetMap world",WorldProject? ExistingWorld=null,bool PreserveEdits=false);
public sealed record OsmWorldPlan(WorldGeoReference GeoReference,int Columns,int Rows,int SectionSize,int Cells,int Width,int Height);
public sealed class OsmWorldImportService(OsmClient client,GameAssetCatalog assets,string directory,StaticModelCatalog? models=null):IDisposable
{
 private readonly StaticModelCatalog modelCatalog=models??new(assets);
 private sealed class Job(string id){public string Id=id;public string Status="queued";public OsmProgress Progress=new("queued",0,0);public DateTimeOffset Created=DateTimeOffset.UtcNow;public string? Error;public string? File;public List<string> Warnings=[];public CancellationTokenSource Cancel=new();public Task? Task;public object Sync=new();}
 private readonly ConcurrentDictionary<string,Job> jobs=new();private readonly object admission=new();private bool disposed;
 public static OsmWorldPlan Plan(OsmWorldImportRequest request){
  if(request is null||string.IsNullOrWhiteSpace(request.Name)||request.Name.Length>80||request.Name.Any(char.IsControl)||request.SectionSize is <256 or >2048||request.SectionSize%256!=0)throw new ArgumentException("Specify a name and section dimensions of 256-2,048 tiles, in multiples of 256.");
  var reference=new WorldGeoReference{Bounds=request.Bounds,MetresPerTile=request.MetresPerTile,OriginCellX=request.OriginCellX,OriginCellY=request.OriginCellY};var size=GeographicProjection.RequiredTiles(reference);var columns=Math.Max(1,(int)Math.Ceiling(size.Width/(double)request.SectionSize));var rows=Math.Max(1,(int)Math.Ceiling(size.Height/(double)request.SectionSize));var cells=checked(columns*rows*(request.SectionSize/256)*(request.SectionSize/256));if(columns*rows>128||cells>8192)throw new ArgumentException("The area requires more than 128 maps or 8,192 native cells. Increase the tile scale or reduce the bounds.");
  // A native world can be larger; a single browser import has a separate bounded memory budget.
  if(cells>768)throw new ArgumentException("This import exceeds the world project's 128 MB budget. Reduce the area or increase the tile size; assemble larger worlds from separately saved sections.");
  if(request.OriginCellX+(columns-1)*request.SectionSize/256>1000||request.OriginCellY+(rows-1)*request.SectionSize/256>1000)throw new ArgumentException("The import exceeds the editor's supported cell coordinates.");
  if(request.ExistingWorld is {} old&&request.PreserveEdits){WorldAssembler.Validate(old);if(old.GeoReference is not {} prior||JsonSerializer.Serialize(prior,NativeMapExporter.JsonOptions)!=JsonSerializer.Serialize(reference,NativeMapExporter.JsonOptions))throw new ArgumentException("To preserve edits, keep the geographic world's original bounds, scale, and coordinate origin.");if(old.Maps.Count!=columns*rows||old.Maps.Any(m=>m.Project.Width!=request.SectionSize||m.Project.Height!=request.SectionSize||(m.Project.WorldX-request.OriginCellX)%(request.SectionSize/256)!=0||(m.Project.WorldY-request.OriginCellY)%(request.SectionSize/256)!=0||m.Project.WorldX<request.OriginCellX||m.Project.WorldY<request.OriginCellY||m.Project.WorldX>=request.OriginCellX+columns*request.SectionSize/256||m.Project.WorldY>=request.OriginCellY+rows*request.SectionSize/256))throw new ArgumentException("The existing world layout differs. To preserve edits, keep the original section dimensions and positions.");}
  return new(reference,columns,rows,request.SectionSize,cells,columns*request.SectionSize,rows*request.SectionSize);
 }
 public object Start(OsmWorldImportRequest request){var plan=Plan(request);lock(admission){ObjectDisposedException.ThrowIf(disposed,this);if(jobs.Values.Any(j=>j.Status is "queued" or "running"))throw new ArgumentException("An OSM import is already running. Wait for it to finish or cancel it.");foreach(var old in jobs.Values.OrderByDescending(j=>j.Created).Skip(7))if(jobs.TryRemove(old.Id,out _)){old.Cancel.Dispose();if(old.File is {} file&&File.Exists(file))File.Delete(file);}var id=Guid.NewGuid().ToString("N");var job=new Job(id){Progress=new("queued",0,plan.Columns*plan.Rows)};jobs[id]=job;var isolated=request with{ExistingWorld=request.PreserveEdits&&request.ExistingWorld is {} world?WorldAssembler.Clone(world):null};job.Task=Task.Run(()=>Run(job,isolated,plan));return new{id,plan};}}
 public object Status(string id){var job=Get(id);lock(job.Sync)return new{id=job.Id,status=job.Status,progress=job.Progress,createdAtUtc=job.Created,error=job.Error,warnings=job.Warnings.ToArray(),ready=job.Status=="completed"};}
 public object Cancel(string id){var job=Get(id);job.Cancel.Cancel();return Status(id);}
 public string ResultFile(string id){var job=Get(id);lock(job.Sync){if(job.Status!="completed"||job.File is null)throw new ArgumentException("The world is not ready. A partial import cannot be returned as a complete project.");return job.File;}}
 private Job Get(string id)=>WorldAssembler.SafeId(id)&&jobs.TryGetValue(id,out var job)?job:throw new ArgumentException("Import task not found.");
 private async Task Run(Job job,OsmWorldImportRequest request,OsmWorldPlan plan){string? temporary=null;try{
  using var deadline=CancellationTokenSource.CreateLinkedTokenSource(job.Cancel.Token);deadline.CancelAfter(TimeSpan.FromMinutes(15));var token=deadline.Token;lock(job.Sync)job.Status="running";
  var progress=new InlineProgress<OsmProgress>(value=>{lock(job.Sync)job.Progress=value;});var download=await client.FetchTiledDetailed(request.Bounds,token,progress,64_000_000);var geometry=new OsmGeometrySet(64_000_000);geometry.Add(download.Data);
  var world=new WorldProject{Name=request.Name,Id=request.ExistingWorld?.Id??Guid.NewGuid().ToString("N"),GeoReference=plan.GeoReference,Buildings=request.PreserveEdits?request.ExistingWorld?.Buildings??[]:[],Elevation=request.PreserveEdits?request.ExistingWorld?.Elevation:null};var total=plan.Columns*plan.Rows;var completed=0;var warnings=new HashSet<string>(download.Warnings){"Map data © OpenStreetMap contributors — https://www.openstreetmap.org/copyright — ODbL 1.0",$"Source: {download.Source}; data date: {download.DataTimestamp??"not specified"}; retrieved: {download.RetrievedAtUtc:O}; requests: {download.Requests}; cache: {(download.FromCache?"yes":"no")}."};
  for(var y=0;y<plan.Rows;y++)for(var x=0;x<plan.Columns;x++){
   token.ThrowIfCancellationRequested();var cellX=request.OriginCellX+x*request.SectionSize/256;var cellY=request.OriginCellY+y*request.SectionSize/256;var projection=new GeographicProjection(plan.GeoReference,cellX,cellY);var bounds=projection.SectionBounds(request.SectionSize,request.SectionSize);var old=request.ExistingWorld?.Maps.SingleOrDefault(m=>m.Project.WorldX==cellX&&m.Project.WorldY==cellY);
   var project=old?.Project??MapGenerator.Generate(new(){Kind="blank",Size=request.SectionSize,Seed=request.Seed,Name=$"{request.Name[..Math.Min(60,request.Name.Length)]} {x+1}/{y+1}"});project.WorldX=cellX;project.WorldY=cellY;project.WorldSection=true;project.Version=Math.Max(project.Version,6);var json=geometry.ForSection(bounds);using var data=JsonDocument.Parse(json);if(data.RootElement.GetProperty("elements").GetArrayLength()>0){var result=GeographicImporter.Import(json,project,bounds,token,request.PreserveEdits,projection);project=result.Project;foreach(var warning in result.Warnings)warnings.Add(warning);}else{project.Bounds=bounds;project.MetresPerTile=request.MetresPerTile;}
   const string attribution="Map data © OpenStreetMap contributors — https://www.openstreetmap.org/copyright — ODbL 1.0";if(!project.Attribution.Contains(attribution))project.Attribution.Add(attribution);AssetRules.Project(project,assets);modelCatalog.Validate(project);world.Maps.Add(new(){Id=old?.Id??Guid.NewGuid().ToString("N"),Project=project});progress.Report(new("compose",++completed,total,download.Source,download.DataTimestamp));
  }
  if(request.PreserveEdits&&request.ExistingWorld is {} priorWorld)foreach(var b in world.Buildings){foreach(var c in WorldAssembler.BuildingCells(b)){var targetMember=WorldAssembler.MemberAt(world,c.X,c.Y);var prior=WorldAssembler.MemberAt(priorWorld,c.X,c.Y);if(targetMember is null||prior is null)continue;var p=targetMember.Project;var oldp=prior.Project;p.Terrain[(c.Y-p.WorldY*256)*p.Width+c.X-p.WorldX*256]=oldp.Terrain[(c.Y-oldp.WorldY*256)*oldp.Width+c.X-oldp.WorldX*256];}if(b.SourceId is not null)foreach(var m in world.Maps)m.Project.Buildings.RemoveAll(local=>local.SourceId==b.SourceId);}
  var worldBuildingWarnings=new List<string>();GeographicImporter.ImportWorldBuildings(download.Data,world,request.Seed,worldBuildingWarnings,token);foreach(var warning in worldBuildingWarnings)warnings.Add(warning);foreach(var b in world.Buildings){AssetRules.Building(b,assets);if(b.Design is {} d)foreach(var f in d.Floors)foreach(var m in f.StaticModels)modelCatalog.Validate(m);}
  WorldAssembler.Validate(world);token.ThrowIfCancellationRequested();Directory.CreateDirectory(directory);var target=Path.Combine(directory,job.Id+".pzworld.json");temporary=target+".tmp";await using(var file=File.Create(temporary)){await using var bounded=new BoundedOutput(file,WorldStore.MaxBytes);await JsonSerializer.SerializeAsync(bounded,world,NativeMapExporter.JsonOptions,token);}token.ThrowIfCancellationRequested();File.Move(temporary,target,true);temporary=null;lock(job.Sync){job.File=target;job.Warnings=warnings.Take(64).ToList();job.Progress=new("completed",total,total,download.Source,download.DataTimestamp);job.Status="completed";}
 }catch(OperationCanceledException){lock(job.Sync){job.Status=job.Cancel.IsCancellationRequested?"cancelled":"failed";job.Error=job.Cancel.IsCancellationRequested?"Import canceled. The original world was preserved.":"Import did not finish within 15 minutes. The original world was preserved.";}}catch(Exception e) when(e is ArgumentException or HttpRequestException or IOException or JsonException or InvalidOperationException){lock(job.Sync){job.Status="failed";job.Error=e.Message;}}finally{if(temporary is not null&&File.Exists(temporary))File.Delete(temporary);}}
 public void Dispose(){lock(admission){disposed=true;foreach(var job in jobs.Values)job.Cancel.Cancel();}}
 private sealed class BoundedOutput(Stream inner,long limit):Stream
 {
  private long count;public override bool CanRead=>false;public override bool CanSeek=>false;public override bool CanWrite=>true;public override long Length=>count;public override long Position{get=>count;set=>throw new NotSupportedException();}private void Check(int n){count+=n;if(count>limit)throw new ArgumentException("The world project exceeds 128 MB. Reduce the imported area.");}public override void Write(byte[] buffer,int offset,int n){Check(n);inner.Write(buffer,offset,n);}public override void Write(ReadOnlySpan<byte> buffer){Check(buffer.Length);inner.Write(buffer);}public override async ValueTask WriteAsync(ReadOnlyMemory<byte> buffer,CancellationToken token=default){Check(buffer.Length);await inner.WriteAsync(buffer,token);}public override void Flush()=>inner.Flush();public override Task FlushAsync(CancellationToken token)=>inner.FlushAsync(token);public override int Read(byte[] buffer,int offset,int count)=>throw new NotSupportedException();public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();
 }
}
